export function ToolGuide({ tool }: { tool: Tool }) {
  const [steps, limits] = tool.slug === "ai-document-intelligence" ? ["Upload or paste source documents, review selected sections and correct the suggested type. Run local invoice checks or text comparison for free. For AI, choose an action, review its credit cost and confirm. Open each finding’s source excerpt before exporting.", "AI accepts up to 24,000 selected characters including your question, at one credit per 6,000 characters. Five files maximum, 20 MB per file and 20 PDF pages. OCR currently uses English; DOCX anchors refer to paragraphs, not pages. Local checks do not establish authenticity or tax compliance."] : toolGuidance[tool.slug];
  const nextSteps: Record<string, string[]> = {
    "pdf-page-organizer": ["pdf-compressor", "searchable-pdf"],
    "searchable-pdf": ["pdf-page-organizer", "pdf-text-extract"],
    "csv-cleaner": ["csv-to-json"],
    "csv-to-json": ["csv-cleaner", "json-validator"],
    "ai-document-intelligence": ["ai-invoice-extractor", "ai-table-extractor"],
  };
  const related = nextSteps[tool.slug]
    ? nextSteps[tool.slug].flatMap(slug => TOOLS.filter(t => t.slug === slug))
    : TOOLS.filter(t => t.category === tool.category && t.slug !== tool.slug).slice(0, 3);
  return <details aria-label={`${tool.name} guidance`} className="w-full space-y-3 pt-4 border-t leading-relaxed">
    <summary className="cursor-pointer font-semibold">How to use this tool{examples[tool.slug] ? " · worked example" : ""}</summary><p>{tool.description}.</p>
    <h3 className="font-semibold">Getting a reliable result</h3><p>{steps}</p>
    {examples[tool.slug] && <><h3 className="font-semibold">Worked example</h3><p>{examples[tool.slug]}</p></>}
    {limits && <><h3 className="font-semibold">Limitations to check</h3><p>{limits}</p></>}
    <p className="text-sm">For network services, accounts and optional usage records, see our <Link className="underline" href="/privacy">privacy policy</Link>.</p>
    <h3 className="font-semibold">Related tools</h3><ul className="flex flex-wrap gap-4">{related.map(t => <li key={t.slug}><Link className="underline" href={`/tools/${t.slug}`}>{t.name}</Link></li>)}</ul>
  </details>;
}


export function WorkflowGuide() {
  return <section aria-labelledby="workflow-guide-heading" className="space-y-4">
    <h2 id="workflow-guide-heading" className="text-2xl font-bold">Finish a task, step by step</h2>
    <div className="grid gap-4 md:grid-cols-3">
      <article className="rounded-xl border p-5 space-y-3"><h3 className="font-semibold">Send a smaller PDF without losing the original</h3><p>Start with a copy. Remove pages the recipient does not need in the <Link className="underline" href="/tools/pdf-page-organizer">PDF Page Organizer</Link>, then try lossless mode in the <Link className="underline" href="/tools/pdf-compressor">PDF Compressor</Link>.</p><p>If a scanned document is still too large, compare image compression with the original at normal reading size. Check small text, signatures and page order before sharing. Image-based output can lose selectable text and interactive fields; keep the source for future editing.</p></article>
      <article className="rounded-xl border p-5 space-y-3"><h3 className="font-semibold">Move a CSV into an application</h3><p>Inspect column headings and a few representative rows in the <Link className="underline" href="/tools/csv-cleaner">CSV Cleaner</Link>. Choose the date order explicitly rather than guessing whether 03/04 means March or April.</p><p>Use <Link className="underline" href="/tools/csv-to-json">CSV to JSON</Link> to create records. Check a name containing a comma, an empty field and an identifier with leading zeroes. Values remain strings; apply the receiving application's types deliberately. Compare record counts before importing the full dataset.</p></article>
      <article className="rounded-xl border p-5 space-y-3"><h3 className="font-semibold">Turn a scan into usable text</h3><p>For a screenshot or photo, start with <Link className="underline" href="/tools/image-ocr">Image to Text</Link>. Use an upright, sharply focused image and the correct language. For a scanned PDF you want to search, use <Link className="underline" href="/tools/searchable-pdf">Searchable PDF OCR</Link>.</p><p>Compare names, dates, totals and punctuation against the scan. OCR can confuse 0 with O or 1 with l. Test search and copy in the downloaded PDF before sending it. These file tools process documents in your browser; selecting a separate AI workflow sends reviewed text to its provider.</p></article>
    </div>
  </section>;
}
